Tone.start();
var synth = new Tone.Synth().toDestination();
var section = 4; //octave
var keys = [81, 50, 87, 51, 69, 82, 53, 84, 54, 89, 55, 85];
var notes = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
var keyLetters = ['Q', '2', 'W', '3', 'E', 'R', '5', 'T', '6', 'Y', '7', 'U', ]
var currentKey = 0;
var pressedFrame;

document.onkeydown = function (e) {
  e = e || window.event;
  let key = e.which || e.keyCode;
  for (let i = 0; i < keys.length; i++) {
    if (key === keys[i]) {
      playNote(notes[i]);
      currentKey = keys[i];
      // console.log(currentKey);
      ghosts.forEach((ghost) => {
        //if key pressed, check which ghost has the key
        ghost.checkKey();
      });
    }
  }
};

function playNote(note) {
  synth.triggerAttackRelease(`${note}4`, "8n");
}

//set an interval if a note is hovered
function hoverNote(note) {
  synth.triggerAttackRelease(`${note}4`, "4n");
}

var num;
var t = 0.0;
var vel = 0.02;
var os;
var ghosts = [];
var count = keys.length;
var marginW, w;

function setup() {
  createCanvas(600, 300);

  overAllTexture = createGraphics(width, height);
  overAllTexture.loadPixels();
  for (var i = 0; i < width + 50; i++) {
    for (var o = 0; o < height + 50; o++) {
      overAllTexture.set(
        i,
        o,
        color(200, noise(i / 10, (i * o) / 300) * random([0, 0, 50, 100]))
      );
    }
  }
  overAllTexture.updatePixels();

  rectMode(CENTER);
  num = random(10);
  marginW = width / 20;
  w = (width - marginW) / count;
  frameRate(30);

  // create enough ghosts for the amount of piano keys
  for (let i = 0; i < keys.length; i++) {
    let pianoKey = keys[i];
    let note = notes[i];
    let keyLetter = keyLetters[i];
    let x = marginW + i * w;
    let ghosty = new Ghost(x, height / 2, w, 0, 0, pianoKey, note, keyLetter);
    ghosts.push(ghosty);
  }
  console.log(ghosts);
}

function draw() {
  randomSeed(num);
  background("#e7944e");
  blendModeimage(overAllTexture, 0, 0);

  blendMode(BLEND)

  // noStroke();
  ghosts.forEach((ghost) => {
    ghost.drawGhost();
  });
  t += vel;
}

class Ghost {
  constructor(x, y, size, os, eyeopen, pianoKey, note, keyLetter) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.os = os;
    this.eyeopen = eyeopen;
    this.pianoKey = pianoKey;
    this.note = note;
    this.keyLetter = keyLetter;
    //offset sharp notes and colour them black
    if (this.note.includes("#")) {
      this.fillColour = 0;
      this.accentColour = 150;
      this.y = y - 20;
    } else {
      this.fillColour = 255;
      this.accentColour = 50;
      this.y = y;
    }
    this.defaultColour = this.fillColour;
    this.shadowBlur = 0;
    this.singing = false;
    this.pressedFrame = 0;
  }

  checkKey() {
    if (currentKey === this.pianoKey) {
      this.pressedFrame = frameCount;
      this.singing = true;
    }
  }

  drawGhost() {

    // if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.x, this.y) < w / 2) {
    //   this.pressedFrame = frameCount;
    //   this.singing = true;
    // } else {
    //   this.singing = false;
    // }

    if(this.singing) {

    this.shadowBlur = 20;
    drawingContext.shadowColor = color(255);
    this.eyeopen = true;
    if (frameCount === this.pressedFrame + 8) {
      this.shadowBlur = 0;
      this.singing = false;
    }
    } else {
      this.eyeopen = false;
    }
    drawingContext.shadowBlur = this.shadowBlur;
    this.os = 20 * sin(t);

    noStroke();
    let osci = this.os;
    let num2 = 2.2; //orig: 4
    let hW = this.size / num2;
    let hH = this.size / (num2-1);
    push();
    translate(this.x, this.y);

    //oscillation------
    translate(0, osci);
    push();
    //leg_shadow-----
    if (this.fillColour > 200) {
    fill(200);
    } else {
      fill(150)
    }

    beginShape();
    vertex(-hW, 0);
    vertex(hW, 0);
    for (let i = hW; i > -hW + 1; i -= 1) {
      let y = hH + (hH / 8) * sin(i / (hW / 10) + t);
      vertex(i, y);
    }
    vertex(-hW, hH);
    endShape();

    //ghost_body-----
    push();
    fill(this.fillColour);
    beginShape();
    vertex(hW, 0);
    bezierVertex(hW * 1.1, -hH * 1.35, -hW * 1.1, -hH * 1.35, -hW, 0);
    vertex(-hW, hH);
    for (let i = -hW; i < hW + 1; i += 1) {
      let y = hH + (hH / 8) * sin(i / (hW / 10) - t);
      vertex(i, y);
    }
    vertex(hW, 0);
    endShape();

    pop();
    pop();
    if (this.eyeopen) {
      //eye-------
      fill(this.accentColour);
      ellipse(-hW / 2 + abs(osci / 5), -hH / 2 + abs(osci / 5), hW / 5);
      ellipse(hW / 5 + abs(osci / 5), -hH / 2 + abs(osci / 5), hW / 5);
    } else {
      stroke(this.accentColour);
      strokeWeight(hW / 10);
      noFill();
      //arc(x, y, w, h, start, stop, [mode], [detail])
      arc(
        -hW / 2 + abs(osci / 5),
        -hH / 2 + abs(osci / 5),
        hW / 5,
        hW / 5,
        TWO_PI,
        PI
      );
      arc(
        hW / 5 + abs(osci / 5),
        -hH / 2 + abs(osci / 5),
        hW / 5,
        hW / 5,
        TWO_PI,
        PI
      );

    }
    noStroke();
    fill(0);
    pop();
    text(this.keyLetter, this.x, this.y+height/3)

  }
}

function mouseReleased() {
  for(let i = 0; i < ghosts.length; i++) {
    let ghostyKid = ghosts[i]
      if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), ghostyKid.x, ghostyKid.y) < w / 2) {
      ghostyKid.pressedFrame = frameCount;
      ghostyKid.singing = true;  
      hoverNote(ghostyKid.note);
      }
  }
}


